head.script:
// 원본 : /listingcommon/ULDSTF92024.gfm (공시안내문작성) — 업무 분석은 같은 폴더의 ULDSTF92024.md
/*
 * 화면 동작
 * 1. 팝업 로딩시 부모 화면의 scwin.getPar 로 서식코드·업무처리번호·발행기관코드·시장구분과 공시 원천 자료를 받는다.
 * 2. 원공시를 조회해 시장을 정하고, 이미 공시된 건이면 정정공시 여부를 묻고 정정공시정보입력 팝업을 연다.
 * 3. 서버에 공시안내문(국문·영문) 생성을 요청해 본문 editor 에 보여 준다.
 *    - 유가증권시장(코스닥 기타시장안내 70837 포함) : 원문 텍스트를 editor 에서 고칠 수 있고, 고친 내용이 전송된다.
 *      단 HTML 변환 대상 서식(HTML_TRNS_FORM_CDS)은 서버가 만든 HTML 을 그대로 보여 주고 인쇄 버튼을 숨긴다.
 *    - 코스닥·코넥스 : 서버가 만든 HTML 을 그대로 보여 준다(전송도 서버 생성분).
 * 4. 「정정공시」 체크·「정정공시 정보입력」 후에는 안내문을 다시 생성한다.
 * 5. 「공시검토전송」 클릭시 관리종목 서식 안내 → 확인 → 원문·첨부파일을 공시검토 단계로 전송하고 닫는다.
 * 6. 「인쇄」 클릭시 결재란·회사명·제목·본문으로 PDF 보고서를 연다.
 *
 * 원본과 달라진 곳 (자세한 근거는 ULDSTF92024.md 「전환 내역」)
 * - 겹쳐 있던 텍스트 영역(tar)·HTML 패널(pan)을 editor(edt_contn) 하나로 합쳤다. 표시 방식은 scwin.contentMode 로 구분한다.
 * - Gauce 파일 컨트롤(fil) + URL 형 컬럼 대신 multiupload(mpd_Fil)로 첨부하고, 전송은 multiupload 한 번으로 보낸다.
 * - 모달 대화상자 뒤에 이어 하던 처리(정정공시 정보입력 → 재생성)를 openPopup await 로 순서를 보장했다.
 * - 화면에 보이지 않던 디버그 영역(log)과, 숨김 처리라 열 수 없던 영문공시안내문 미리보기(ULDSTF92024_EN) 진입점은 옮기지 않았다.
 */
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF92024";

// 부모 화면이 넘긴 키 (원본 stKeyFrm / stKeyBiz / stKeyIsurCd / stKeyMktId / stKeyMsg / stKeyTit)
scwin.keyFrm = "";      // 서식코드
scwin.keyBiz = "";      // 업무처리번호 (여러 건이면 쉼표 구분)
scwin.keyIsurCd = "";   // 발행기관코드
scwin.keyMktId = "";    // 시장구분 (1 유가, 2 코스닥, 6 코넥스) — 비면 원공시의 시장구분을 쓴다
scwin.keyMsg = "";      // 생성하지 않는 서식일 때 본문에 그대로 넣을 문구
scwin.keyTit = "";      // 공시제목 기본값

scwin.isNoGen = false;          // 서버 생성 없이 keyMsg 를 본문으로 쓰는 서식 여부 (원본 isNoGen)
scwin.isHtmlTrnsForm = false;   // 유가 서식 중 HTML 로 변환해 보여 주는 서식 여부 (원본 formTrnsCodeYN)
scwin.contentMode = "text";     // 본문 표시 방식 : text(원문 텍스트, 수정·전송) / html(서버 생성 HTML 표시)

scwin.NO_SRC_DSET = "원본 DATASET이 존재하지 않아 공시문서를 생성할 수 없습니다.";

// 유가 서식 중 HTML 변환 대상 서식코드 (2011.08.16 추가분)
scwin.HTML_TRNS_FORM_CDS = [
    "68060", "68061", "68061C", "68054",                    // 매매거래정지·정지해제(유)
    "68918", "68919A", "68919B", "68920",                   // 매매거래정지·해제(수익증권)
    "68921", "68922A", "68922B", "68923",                   // 매매거래정지·해제(신주인수권증권)
    "68924", "68925A", "68925B", "68916",                   // 매매거래정지·해제(신주인수권증서)
    "68052", "68052A", "68052B", "68052C", "68052D", "68052E", "68052F",   // 관리종목지정(유,주권)
    "68055", "68055A", "68055B", "68055C", "68055D", "68055E", "68055F",   // 관리종목지정 사유변경(유,주권)
    "68053", "68053A", "68053B", "68053C", "68053D", "68053E", "68053F",   // 관리종목지정 해제(유,주권)
    "99350", "99351", "99352",                              // 관리종목 지정·사유변경·해제(ETF)
    "69805", "69806", "69807",                              // 관리종목 지정·사유변경·해제(상장형 수익증권)
    "68059", "68056", "68064", "68065",                     // 관리종목 사유·유의사항 변경, 상장폐지기준 적용 유예·기간변경
    "68051A", "68051B", "68913", "68917", "68909", "68909A", // 상장폐지·상장폐지예고(유)
    "68212A", "68212B", "68212C",                           // 결산기·분배기준일 변경
    "68058", "68066",                                       // 업종 변경, 존립기간변경
    "68377"                                                 // ETN LP 보유량 공시
];

// 전송 전에 확인절차 대상법인 안내를 띄우는 서식코드
scwin.MNG_DESIG_FORM_CDS = ["68052", "68052A", "68052B", "68052C", "68052D", "68052E", "68052F"];   // 유가 관리종목지정
scwin.MNG_RELS_FORM_CDS = ["68053", "68053A", "68053B", "68053C", "68053D", "68053E", "68053F"];    // 유가 관리종목지정해제

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 20
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92024.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 20
 * @description 초기화. 부모 화면이 넘긴 키와 원천 자료를 받고, 원공시로 시장·정정공시 여부를 정한 뒤 공시안내문을 생성한다.
 *
 * 부모 화면은 scwin.getPar(arr, dlt_Isu, dlt_Mst, dlt_2, dlt_3, dlt_4, dlt_IsuEng, dlt_MstEng, dlt_DtlEng, dlt_RsnAllEng, dlt_RsnRelEng, dlt_5 ~ dlt_9) 를 갖는다.
 * arr : [0] 서식코드 [1] 업무처리번호 [2] 발행기관코드 [3] 시장구분 [4] 생성하지 않는 서식의 본문(있으면 isNoGen) [5] 공시제목
 * 부모에 getPar 가 없으면 원본과 같이 아무것도 하지 않는다.
 * @param
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 인쇄는 유가증권시장 사용자에게만 보인다 (원본 panel_PRINT).
    const userMarket = $c.session.getUserInfo("market");
    if (userMarket === "2" || userMarket === "6") {
        btn_Print.hide();
    }

    const parentScwin = $c.win.getParent()?.scwin;
    if (typeof parentScwin?.getPar !== "function") return;

    const arr = [];
    parentScwin.getPar(arr, dlt_Isu, dlt_Mst, dlt_2, dlt_3, dlt_4, dlt_IsuEng, dlt_MstEng, dlt_DtlEng, dlt_RsnAllEng, dlt_RsnRelEng,
        dlt_5, dlt_6, dlt_7, dlt_8, dlt_9);

    scwin.keyFrm = arr[0] ?? "";
    scwin.keyBiz = arr[1] ?? "";
    scwin.keyIsurCd = arr[2] ?? "";
    scwin.keyMktId = arr[3] ?? "";
    scwin.isNoGen = (arr.length >= 5);
    scwin.keyMsg = arr[4] ?? "";
    scwin.keyTit = arr[5] ?? "";

    // BDC BB 신규상장은 본문 문구를 넘겨도 서버에서 생성한다.
    if (scwin.keyFrm.startsWith("73033")) {
        scwin.isNoGen = false;
    }

    scwin.isHtmlTrnsForm = scwin.HTML_TRNS_FORM_CDS.includes(scwin.keyFrm);

    await scwin.selectOriDiscls();

    const lstMktId = scwin.getLstMktId();
    const isDisclosed = (dlt_Ori.getCellData(0, "MOD_YN") === "Y");   // 이미 공시된 건이면 정정공시 대상

    btn_crt.show("");

    if (scwin.isEditableDiscls(lstMktId)) {
        // 유가증권시장(코스닥 기타시장안내 포함) : 원문을 고칠 수 있다. HTML 변환 서식만 HTML 로 보여 주고 인쇄를 막는다.
        if (scwin.isHtmlTrnsForm) {
            scwin.contentMode = "html";
            btn_Print.hide();
        } else {
            scwin.contentMode = "text";
        }
        btn_crt.hide();

        if (isDisclosed) {
            // "MSG-0907" : 이미 공시처리되었습니다. 정정공시처리하시겠습니까?
            if (await $c.win.confirm($c.stf.getMessageParam("MSG-0907", ""))) {
                dma_disclsInf.set("CORRCT_YN", "Y");
                await scwin.openCrtInfo();
                btn_crt.show("");
            }
        } else {
            // 신규공시는 정정할 수 없다.
            chk_CorrctYn.setDisabled(true);
        }
    } else if (lstMktId === "2" || lstMktId === "6") {
        // 코스닥·코넥스 : 서버가 만든 HTML 을 그대로 보여 준다.
        scwin.contentMode = "html";

        if (isDisclosed) {
            if (await $c.win.confirm($c.stf.getMessageParam("MSG-0907", ""))) {
                dma_disclsInf.set("CORRCT_YN", "Y");
                await scwin.openCrtInfo();
            }
        } else {
            chk_CorrctYn.setDisabled(true);
        }
    }

    // 자료 조회 직후 공시문서 작성
    await scwin.genDiscls();
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_Print_onclick
 * @author Inswave
 * @date 2026. 10. 20
 * @description 인쇄 버튼 클릭. 공시안내문을 PDF 보고서로 연다.
 * @param
 * @returns
 * @hidden N
 */
scwin.btn_Print_onclick = async function (e) {
    try {
        await scwin.printDiscls();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92024.btn_Print_onclick" });
    }
};

/**
 * @event
 * @name scwin.chk_CorrctYn_onviewchange
 * @author Inswave
 * @date 2026. 10. 20
 * @description 정정공시 체크 변경. 정정구분을 반영해 공시안내문을 다시 생성한다.
 * @param
 * @returns
 * @hidden N
 */
scwin.chk_CorrctYn_onviewchange = async function (info) {
    try {
        await scwin.genDiscls();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92024.chk_CorrctYn_onviewchange" });
    }
};

/**
 * @event
 * @name scwin.btn_crt_onclick
 * @author Inswave
 * @date 2026. 10. 20
 * @description 정정공시 정보입력 버튼 클릭. 정정공시정보입력 팝업이 닫힌 뒤 공시안내문을 다시 생성한다.
 * @param
 * @returns
 * @hidden N
 */
scwin.btn_crt_onclick = async function (e) {
    try {
        await scwin.openCrtInfo();
        await scwin.genDiscls();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92024.btn_crt_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_send_onclick
 * @author Inswave
 * @date 2026. 10. 20
 * @description 공시검토전송 버튼 클릭. 유가 관리종목 지정·해제 서식이면 확인절차 대상법인 안내를 먼저 띄우고, 확인을 받아 전송한다.
 * @param
 * @returns
 * @hidden N
 */
scwin.btn_send_onclick = async function (e) {
    try {
        if (scwin.MNG_DESIG_FORM_CDS.includes(scwin.keyFrm)) {
            await $c.win.alert("관리종목으로 지정된 법인은 지정일부터 공시내용 확인절차 대상법인입니다.\n"
                + "동사에 대한 확인절차 대상법인 지정 조치 여부를 반드시 확인하시기 바랍니다.");
        }

        if (scwin.MNG_RELS_FORM_CDS.includes(scwin.keyFrm)) {
            await $c.win.alert("관리종목 지정해제된 법인은 해제된 날로부터 3년이 경과하면 공시내용 확인절차 대상법인에서 지정해제 됩니다.\n"
                + "동사의 확인절차 대상법인 지정해제예정일을 반드시 확인하시기 바랍니다.\n"
                + "*[공시관리] > [공시내용 확인절차 대상] > [확인절차 대상법인] > [대상법인 현황]");
        }

        // "MSG-0024" : 공시검토단계로 전송하시겠습니까?
        if (!await $c.win.confirm($c.stf.getMessageParam("MSG-0024", ""))) return;

        await scwin.sendDisclsTotal();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92024.btn_send_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_close_onclick
 * @author Inswave
 * @date 2026. 10. 20
 * @description 닫기 버튼 클릭
 * @param
 * @returns
 * @hidden N
 */
scwin.btn_close_onclick = async function (e) {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92024.btn_close_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_ins_onclick
 * @author Inswave
 * @date 2026. 10. 20
 * @description 첨부파일 추가(폴더) 버튼 클릭. 파일 선택 대화상자를 연다. 고른 파일은 mpd_Fil_selectCallback 이 목록에 넣는다.
 * @param
 * @returns
 * @hidden N
 */
scwin.btn_ins_onclick = function (e) {
    try {
        $c.util.onUploadClick(mpd_Fil);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92024.btn_ins_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_del_onclick
 * @author Inswave
 * @date 2026. 10. 20
 * @description 첨부파일 삭제 버튼 클릭. 선택한 첨부파일을 목록과 전송 대상에서 뺀다.
 * @param
 * @returns
 * @hidden N
 */
scwin.btn_del_onclick = function (e) {
    try {
        const rowIndex = dlt_Fil.getRowPosition();

        if (rowIndex < 0) {
            $c.win.alert($c.data.getMessage("com_crud_0199", "삭제할 첨부파일"));
            return;
        }

        const fileName = dlt_Fil.getCellData(rowIndex, "fileInfo");

        if (!$c.util.isEmpty(fileName)) {
            mpd_Fil.removeFile(fileName);
        }

        dlt_Fil.removeRow(rowIndex);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92024.btn_del_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.selectOriDiscls
 * @author Inswave
 * @date 2026. 10. 20
 * @description 업무처리번호로 원공시(원공시번호·시장구분·기공시여부)를 조회해 dlt_Ori 에 담는다.
 *
 * AS-IS : /listingCommon.do?method=listGeneral, queryId=lds.stf.lstproc.marketaction.oridiscls.select ({P}P1~P3 = 업무처리번호)
 * TODO : 서버 API 경로·응답 구조 확정
 * @param
 * @returns
 * @hidden N
 */
scwin.selectOriDiscls = async function () {
    dlt_Ori.removeAll();

    const sbmOptions = {
        id : "sbm_selectOriDiscls",
        method : "get",
        action : "/api/listing/listingcommon/disclosure/ori-discls",
        target : "dlt_Ori=body",
        isProcessMsg : false
    };

    const requestData = {
        bzProcsNo : scwin.keyBiz
    };

    await $c.sbm.executeDynamic(sbmOptions, requestData);
};

/**
 * @method
 * @name scwin.selectDisclsName
 * @author Inswave
 * @date 2026. 10. 20
 * @description 생성하지 않는 서식(isNoGen)의 공시명을 서식코드·기준일로 조회해 dlt_Tit 에 담는다.
 *
 * AS-IS : /listingCommon.do?method=listGeneral, queryId=lds.stf.lstproc.marketaction.dsclname.select ({P}1 = 오늘, {P}2 = 서식코드)
 * TODO : 서버 API 경로·응답 구조 확정
 * @param
 * @returns
 * @hidden N
 */
scwin.selectDisclsName = async function () {
    dlt_Tit.removeAll();

    const sbmOptions = {
        id : "sbm_selectDisclsName",
        method : "get",
        action : "/api/listing/listingcommon/disclosure/discls-name",
        target : "dlt_Tit=body",
        isProcessMsg : false
    };

    const requestData = {
        baseDd : $c.date.getServerDateTime(),
        formCd : scwin.keyFrm
    };

    await $c.sbm.executeDynamic(sbmOptions, requestData);
};

/**
 * @method
 * @name scwin.generateDisclsTotal
 * @author Inswave
 * @date 2026. 10. 20
 * @description 공시 기본정보와 부모가 넘긴 원천 자료로 국문·영문 공시원문과 공시명을 생성한다. 결과는 dlt_Rst·dlt_RstEng·dlt_Tit 에 담긴다.
 *
 * AS-IS : /listingCommon.do?method=generateDisclosureTotal
 *   JSP(O:pRstEng=dts_Rst_Eng, O:pOut=dts_Rst, O:pTit=dts_Tit, I:pInf=dts_Inf, I:pIn0=dts_Mst, I:pIn1=dts_Isu, I:pIn2=dts_2, I:pIn3=dts_3, I:pIn4=dts_4,
 *       I:pIn5=dts_Isu_Eng, I:pIn6=dts_Mst_Eng, I:pIn7=dts_Dtl_Eng, I:pIn8=dts_Rsn_All_Eng, I:pIn9=dts_Rsn_Rel_Eng, I:pInfEng=dts_Inf_Eng, I:pIn10~14=dts_5~9)
 * 요청 키는 원본 전문 파라미터명을 그대로 쓴다. TODO : 서버 API 경로·요청/응답 구조 확정
 * @param
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.generateDisclsTotal = async function () {
    const sbmOptions = {
        id : "sbm_generateDisclsTotal",
        method : "post",
        action : "/api/listing/listingcommon/disclosure/generate",
        mediatype : "application/json",
        target : "dlt_Rst=body.pOut,dlt_RstEng=body.pRstEng,dlt_Tit=body.pTit",
        isProcessMsg : true
    };

    const requestData = {
        pInf : dlt_Inf.getAllJSON(),
        pInfEng : dlt_InfEng.getAllJSON(),
        pIn0 : dlt_Mst.getAllJSON(),
        pIn1 : dlt_Isu.getAllJSON(),
        pIn2 : dlt_2.getAllJSON(),
        pIn3 : dlt_3.getAllJSON(),
        pIn4 : dlt_4.getAllJSON(),
        pIn5 : dlt_IsuEng.getAllJSON(),
        pIn6 : dlt_MstEng.getAllJSON(),
        pIn7 : dlt_DtlEng.getAllJSON(),
        pIn8 : dlt_RsnAllEng.getAllJSON(),
        pIn9 : dlt_RsnRelEng.getAllJSON(),
        pIn10 : dlt_5.getAllJSON(),
        pIn11 : dlt_6.getAllJSON(),
        pIn12 : dlt_7.getAllJSON(),
        pIn13 : dlt_8.getAllJSON(),
        pIn14 : dlt_9.getAllJSON()
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

    return (result.responseJSON?.success === true);
};

/**
 * @method
 * @name scwin.sendDisclsTotal
 * @author Inswave
 * @date 2026. 10. 20
 * @description 공시원문(국문·영문)과 공시 기본정보, 첨부파일을 공시검토 단계로 전송한다. 완료 처리는 mpd_Fil_onComplete 에서 한다.
 *
 * 원문을 고칠 수 있는 화면(isNoGen 이거나 유가 시장, HTML 변환 서식 제외)은 editor 의 텍스트를 한 줄씩 dlt_Rst 로 옮겨 보낸다.
 * 그 밖에는 서버가 생성한 원문을 그대로 보낸다. 원문 첫 행은 원본과 같이 XHTML DOCTYPE 선언으로 바꾼다.
 *
 * AS-IS : /listingCommon.do?method=sendDisclosureTotal
 *   JSP(I:pInf=dts_Inf, I:pRst=dts_Rst, I:pFil=dts_Fil, I:pIsu=dts_Isu, I:pInfEng=dts_Inf_Eng, I:pRstEng=dts_Rst_Eng)
 * TODO : 서버 API 경로·요청 파라미터명(sendDisclosureRequestDto) 확정
 * @param
 * @returns
 * @hidden N
 */
scwin.sendDisclsTotal = async function () {
    if ($c.util.isEmpty(scwin.keyFrm) || $c.util.isEmpty(scwin.keyIsurCd) || $c.util.isEmpty(scwin.keyBiz)) {
        await $c.win.alert(scwin.NO_SRC_DSET);
        return;
    }

    const docType = "<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">";

    if (dlt_Rst.getRowCount() > 0) {
        dlt_Rst.setCellData(0, "HTML_CONTN", docType);
    }
    if (dlt_RstEng.getRowCount() > 0) {
        dlt_RstEng.setCellData(0, "HTML_CONTN", docType);
    }

    if ((scwin.isNoGen || dlt_Inf.getCellData(0, "SPOT_ISU_TRD_MKT_TP_CD") === "1") && !scwin.isHtmlTrnsForm) {
        scwin.textToRows(dlt_Rst, scwin.getContentText());
    }

    // 공시원문이 있어야 전송할 수 있다.
    if (dlt_Rst.getRowCount() === 0) {
        await $c.win.alert(scwin.NO_SRC_DSET);
        return;
    }

    scwin.setInfRow(dlt_Inf, scwin.keyFrm);
    scwin.setInfRow(dlt_InfEng, scwin.keyFrm + "_EN");

    const requestDto = {
        pInf : dlt_Inf.getAllJSON(),
        pRst : dlt_Rst.getAllJSON(),
        pFil : dlt_Fil.getAllJSON(),
        pIsu : dlt_Isu.getAllJSON(),
        pInfEng : dlt_InfEng.getAllJSON(),
        pRstEng : dlt_RstEng.getAllJSON(),
        fileCnt : dlt_Fil.getRowCount()
    };

    mpd_Fil.changeAction("/api/listing/listingcommon/disclosure/send");
    mpd_Fil.setParam(0, "sendDisclosureRequestDto", JSON.stringify(requestDto));
    mpd_Fil.startUpload();
};

/**
 * @method
 * @name scwin.mpd_Fil_selectCallback
 * @author Inswave
 * @date 2026. 10. 20
 * @description 첨부파일 선택 완료. 방금 고른 파일을 첨부파일 목록에 추가한다.
 * @param {Array} fileInfoArr 선택한 파일 정보
 * @returns
 * @hidden N
 */
scwin.mpd_Fil_selectCallback = function (fileInfoArr) {
    const fileInfos = mpd_Fil.getFileInfos();

    if ($c.util.isEmpty(fileInfos)) return;

    // 방금 추가된 파일은 항상 목록의 마지막이다.
    const fileInfo = fileInfos[fileInfos.length - 1];
    const rowIndex = dlt_Fil.insertRow(dlt_Fil.getRowCount());

    dlt_Fil.setCellData(rowIndex, "fileInfo", fileInfo.name);
    dlt_Fil.setCellData(rowIndex, "fileSz", fileInfo.size);
};

/**
 * @method
 * @name scwin.mpd_Fil_onComplete
 * @author Inswave
 * @date 2026. 10. 20
 * @description 공시검토전송 완료. 처리 완료를 알리고 팝업을 닫는다.
 * @param
 * @returns
 * @hidden N
 */
scwin.mpd_Fil_onComplete = async function () {
    try {
        // "MSG-0001" : 성공적으로 처리되었습니다.
        await $c.win.alert($c.stf.getMessageParam("MSG-0001", ""));
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92024.mpd_Fil_onComplete" });
    }
};

/**
 * @method
 * @name scwin.mpd_Fil_onerror
 * @author Inswave
 * @date 2026. 10. 20
 * @description 공시검토전송 실패.
 * @param {Object} data 오류 정보
 * @returns
 * @hidden N
 */
scwin.mpd_Fil_onerror = async function (data) {
    try {
        // "MSG-0002" : 작업처리 중 오류가 발생하였습니다.
        await $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92024.mpd_Fil_onerror" });
    }
};

/**
 * @method
 * @name scwin.selectPrintCondition
 * @author Inswave
 * @date 2026. 10. 20
 * @description 인쇄에 쓸 회사명을 발행기관코드로 조회한다.
 *
 * AS-IS : /listingCommon.do?method=listGeneral, outputMessageId=INSIDE_DRAFT_PRINT_OUT,
 *         queryId=lds.stf.lstproc.lstlst.select.inner.draft.print.condition ({P}param01 = 발행기관코드)
 * TODO : 서버 API 경로·응답 구조 확정
 * @param
 * @returns {Promise<String>} 회사명
 * @hidden N
 */
scwin.selectPrintCondition = async function () {
    const sbmOptions = {
        id : "sbm_selectPrintCondition",
        method : "get",
        action : "/api/listing/listingcommon/disclosure/print-condition",
        isProcessMsg : false
    };

    const requestData = {
        isurCd : scwin.keyIsurCd
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

    return result.responseJSON?.body?.COM_NM ?? "";
};

