scwin.fn_setPar = function (arr) {
};

/**
 * @method
 * @name scwin.genDiscls
 * @author Inswave
 * @date 2026. 10. 20
 * @description 공시안내문을 생성해 화면에 보여 준다 (원본 fn_genDisclsTotal).
 * - 원천 자료(dlt_Mst·dlt_2·dlt_3 중 하나라도 행이 있음)가 있으면 서버 생성
 * - 없고 생성하지 않는 서식(isNoGen)이면 공시명만 조회하고 부모가 넘긴 문구를 본문으로 쓴다
 * - 둘 다 아니면 원본 자료 없음 안내
 * 부모가 넘긴 공시제목이 있으면 제목칸에 넣는다.
 * @param
 * @returns
 * @hidden N
 */
scwin.genDiscls = async function () {
    if ($c.util.isEmpty(scwin.keyFrm) || $c.util.isEmpty(scwin.keyIsurCd) || $c.util.isEmpty(scwin.keyBiz)) {
        // "MSG-0908" : 원본 데이터를 조회할 수 없어 공시문서를 생성할 수 없습니다.
        await $c.win.alert($c.stf.getMessageParam("MSG-0908", ""));
        return;
    }

    if (dlt_Mst.getRowCount() > 0 || dlt_2.getRowCount() > 0 || dlt_3.getRowCount() > 0) {
        scwin.setInfRow(dlt_Inf, scwin.keyFrm);
        scwin.setInfRow(dlt_InfEng, scwin.keyFrm + "_EN");

        if (await scwin.generateDisclsTotal()) {
            scwin.showDiscls();
        }
    } else if (scwin.isNoGen) {
        await scwin.selectDisclsName();
        dma_disclsInf.set("DISCLS_NM", dlt_Tit.getCellData(0, "DISCLS_TITLE"));
        scwin.setContentText(scwin.keyMsg);
    } else {
        await $c.win.alert($c.stf.getMessageParam("MSG-0908", ""));
    }

    if (!$c.util.isEmpty(scwin.keyTit)) {
        dma_disclsInf.set("DISCLS_TITLE", scwin.keyTit);
    }
};

/**
 * @method
 * @name scwin.showDiscls
 * @author Inswave
 * @date 2026. 10. 20
 * @description 생성된 공시원문(dlt_Rst 각 행)을 줄바꿈으로 이어 본문에 보여 주고, 공시명을 제목칸에 넣는다 (원본 OnSuccessAfterSearch).
 * 원문을 고칠 수 있는 시장이면 contentMode(text/html)에 따라, 코스닥·코넥스면 HTML 로 보여 준다.
 * @param
 * @returns
 * @hidden N
 */
scwin.showDiscls = function () {
    const lines = [];
    for (let i = 0; i < dlt_Rst.getRowCount(); i++) {
        lines.push(dlt_Rst.getCellData(i, "HTML_CONTN"));
    }
    const contn = lines.join("\n");

    const lstMktId = scwin.getLstMktId();

    if (scwin.isEditableDiscls(lstMktId)) {
        if (scwin.contentMode === "html") {
            edt_contn.setHTML(contn);
        } else {
            scwin.setContentText(contn);
        }
    } else if (lstMktId === "2" || lstMktId === "6") {
        edt_contn.setHTML(contn);
    }

    dma_disclsInf.set("DISCLS_NM", dlt_Tit.getCellData(0, "DISCLS_TITLE"));
};

/**
 * @method
 * @name scwin.openCrtInfo
 * @author Inswave
 * @date 2026. 10. 20
 * @description 정정공시정보입력(ULDSTF92019) 팝업을 열고 닫힐 때까지 기다린다 (원본 fn_getCrtInfo).
 * 팝업은 이 화면의 scwin.fn_getPar 로 dlt_Inf·dlt_InfEng 를 받아 정정 정보를 채운다.
 * TODO : ULDSTF92019 전환 후 경로·수신 규약 확인
 * @param
 * @returns
 * @hidden N
 */
scwin.openCrtInfo = async function () {
    const options = {
        id : "ULDSTF92019",
        popupName : "정정공시정보입력",
        width : 740,
        height : 300,
        frameModal : "top"
    };

    await $c.win.openPopup("/ui/lst/common/ULDSTF92019.xml", options);
};

/**
 * @method
 * @name scwin.printDiscls
 * @author Inswave
 * @date 2026. 10. 20
 * @description 공시안내문을 PDF 보고서로 연다 (원본 fn_print).
 * ELW 상장폐지 서식(68955C·68956C)은 결재란 없는 RLDSTF00004_1, 나머지는 부서별 결재란을 넣은 RLDSTF00004 를 쓴다.
 * 본문은 원문 텍스트의 줄바꿈을 br, 공백을 nbsp 로 바꿔 넘긴다.
 * @param
 * @returns
 * @hidden N
 */
scwin.printDiscls = async function () {
    const isElwDelist = (scwin.keyFrm === "68956C" || scwin.keyFrm === "68955C");   // ELW 상장폐지예고 / 상장폐지(최종거래일)
    const rptName = isElwDelist ? "RLDSTF00004_1" : "RLDSTF00004";
    const approval = isElwDelist ? ["", ""] : scwin.getApprovalNames($c.session.getUserInfo("depCd") ?? "");

    const comNm = await scwin.selectPrintCondition();

    const disclsNm = dma_disclsInf.get("DISCLS_NM");
    const disclsTitle = dma_disclsInf.get("DISCLS_TITLE");
    const subTitle = $c.util.isEmpty(disclsTitle) ? disclsNm : disclsNm + " (" + disclsTitle + ")";

    let body = scwin.getContentText();
    body = $c.util.isEmpty(body) ? "&nbsp;" : body.replaceAll("\n", "<br>").replaceAll(" ", "&nbsp;");

    const nbsp = (value) => ($c.util.isEmpty(value) ? "&nbsp;" : value);

    const userParam = [
        { uid : "DEP_NM_1", unm : nbsp(approval[0]) },
        { uid : "DEP_NM_2", unm : nbsp(approval[1]) },
        { uid : "ISUR_CD", unm : nbsp(scwin.keyIsurCd) },
        { uid : "COM_NM", unm : nbsp(comNm) },
        { uid : "TITLE", unm : nbsp(subTitle) },
        { uid : "BODY", unm : body }
    ];

    $c.print.openReportPdf(rptName, userParam);
};

/**
 * @method
 * @name scwin.getApprovalNames
 * @author Inswave
 * @date 2026. 10. 20
 * @description 로그인 사용자 부서코드로 인쇄 결재란 두 칸의 이름을 정한다.
 * - 2B(유가증권 상품상장팀) : 확인 / 팀장
 * - 2615(기업심사팀) : 팀장 / 상장부장
 * - 26 : 팀장 / 공시총괄팀,  25 : 팀장 / 상장부장,  그 밖 : 팀장 / 공시총괄팀
 * @param {String} depCd 부서코드
 * @returns {Array} [결재란1, 결재란2]
 * @hidden N
 */
scwin.getApprovalNames = function (depCd) {
    const depGrp = depCd.substring(0, 2);

    if (depGrp === "2B") return ["확인", "팀장"];
    if (depCd === "2615") return ["팀장", "상장부장"];
    if (depGrp === "25") return ["팀장", "상장부장"];

    return ["팀장", "공시총괄팀"];
};

/**
 * @method
 * @name scwin.setInfRow
 * @author Inswave
 * @date 2026. 10. 20
 * @description 공시 기본정보 첫 행(없으면 추가)에 발행기관코드·업무처리번호·원공시번호·시장구분·공시제목·서식코드·정정구분을 채운다.
 * 시장구분은 부모가 지정한 값(1·2·6)을 우선하고, 없으면 원공시의 시장구분을 쓴다.
 * @param {Object} dataList 공시 기본정보 dataList (dlt_Inf / dlt_InfEng)
 * @param {String} formCd 서식코드 (영문은 서식코드 + "_EN")
 * @returns
 * @hidden N
 */
scwin.setInfRow = function (dataList, formCd) {
    if (dataList.getRowCount() === 0) {
        dataList.insertRow(0);
    }

    dataList.setCellData(0, "ISUR_CD", scwin.keyIsurCd);
    dataList.setCellData(0, "BZ_PROCS_NO", scwin.keyBiz);
    dataList.setCellData(0, "ACPT_NO", dlt_Ori.getCellData(0, "ACPT_NO"));
    dataList.setCellData(0, "SPOT_ISU_TRD_MKT_TP_CD", scwin.getLstMktId());
    dataList.setCellData(0, "DISCLS_TITLE", dma_disclsInf.get("DISCLS_TITLE"));
    dataList.setCellData(0, "FORM_CD", formCd);
    dataList.setCellData(0, "CORRCT_YN", scwin.getCorrctYn());
};

/**
 * @method
 * @name scwin.textToRows
 * @author Inswave
 * @date 2026. 10. 20
 * @description 원문 텍스트를 줄 단위로 나눠 공시원문 dataList 의 행으로 옮긴다 (원본 txt2dts). 줄 끝의 CR 은 지운다.
 * @param {Object} dataList 공시원문 dataList
 * @param {String} text 원문 텍스트
 * @returns
 * @hidden N
 */
scwin.textToRows = function (dataList, text) {
    dataList.removeAll();

    const lines = text.split("\n");
    for (let i = 0; i < lines.length; i++) {
        const rowIndex = dataList.insertRow(dataList.getRowCount());
        dataList.setCellData(rowIndex, "HTML_CONTN", lines[i].replace(/\r$/, ""));
    }
};

/**
 * @method
 * @name scwin.getLstMktId
 * @author Inswave
 * @date 2026. 10. 20
 * @description 상장시장 구분을 정한다. 부모가 지정한 시장구분(1·2·6)을 우선하고, 없으면 원공시의 시장구분을 쓴다.
 * @param
 * @returns {String} 시장구분 (1 유가, 2 코스닥, 6 코넥스)
 * @hidden N
 */
scwin.getLstMktId = function () {
    if (["1", "2", "6"].includes(scwin.keyMktId)) {
        return scwin.keyMktId;
    }
    return dlt_Ori.getCellData(0, "SPOT_ISU_TRD_MKT_TP_CD");
};

/**
 * @method
 * @name scwin.isEditableDiscls
 * @author Inswave
 * @date 2026. 10. 20
 * @description 원문을 화면에서 고칠 수 있는 공시인지 확인한다. 유가증권시장이거나, 코스닥·코넥스의 기타시장안내(서식 70837) 이면 고칠 수 있다.
 * @param {String} lstMktId 시장구분
 * @returns {Boolean} 고칠 수 있으면 true
 * @hidden N
 */
scwin.isEditableDiscls = function (lstMktId) {
    return lstMktId === "1" || ((lstMktId === "2" || lstMktId === "6") && scwin.keyFrm.substring(0, 5) === "70837");
};

/**
 * @method
 * @name scwin.getCorrctYn
 * @author Inswave
 * @date 2026. 10. 20
 * @description 정정공시 체크 여부를 Y/N 으로 돌려준다.
 * @param
 * @returns {String} Y / N
 * @hidden N
 */
scwin.getCorrctYn = function () {
    return (dma_disclsInf.get("CORRCT_YN") === "Y") ? "Y" : "N";
};

/**
 * @method
 * @name scwin.setContentText
 * @author Inswave
 * @date 2026. 10. 20
 * @description 원문 텍스트를 editor 에 넣는다. 줄과 공백이 그대로 보이도록 HTML 로 바꿔 넣는다.
 * @param {String} text 원문 텍스트
 * @returns
 * @hidden N
 */
scwin.setContentText = function (text) {
    edt_contn.setHTML(scwin.textToHtml(text ?? ""));
};

/**
 * @method
 * @name scwin.getContentText
 * @author Inswave
 * @date 2026. 10. 20
 * @description editor 의 내용을 원문 텍스트(줄바꿈 구분)로 돌려준다.
 * @param
 * @returns {String} 원문 텍스트
 * @hidden N
 */
scwin.getContentText = function () {
    return scwin.htmlToText(edt_contn.getHTML() ?? "");
};

/**
 * @method
 * @name scwin.textToHtml
 * @author Inswave
 * @date 2026. 10. 20
 * @description 텍스트를 editor 용 HTML 로 바꾼다. 한 줄을 문단 하나로, 특수문자는 엔티티로, 공백은 nbsp 로 바꾼다(정렬용 공백 보존).
 * @param {String} text 원문 텍스트
 * @returns {String} HTML
 * @hidden N
 */
scwin.textToHtml = function (text) {
    return text.split("\n").map((line) => {
        const escaped = line.replace(/\r$/, "")
            .replaceAll("&", "&amp;")
            .replaceAll("<", "&lt;")
            .replaceAll(">", "&gt;")
            .replaceAll(" ", "&nbsp;");
        return "<p>" + (escaped === "" ? "&nbsp;" : escaped) + "</p>";
    }).join("");
};

/**
 * @method
 * @name scwin.htmlToText
 * @author Inswave
 * @date 2026. 10. 20
 * @description editor HTML 을 텍스트로 바꾼다. 문단·br 을 줄바꿈으로, nbsp 를 공백으로 바꾸고 태그는 지운다.
 * @param {String} html editor HTML
 * @returns {String} 원문 텍스트
 * @hidden N
 */
scwin.htmlToText = function (html) {
    // nbsp 하나뿐인 문단은 textToHtml 이 빈 줄 자리에 넣은 것이라 빈 문단으로 되돌린다.
    const marked = html
        .replace(/<p([^>]*)>(?:&nbsp;|&#160;| )<\/p>/gi, "<p$1></p>")
        .replace(/<br\s*\/?>/gi, "\n")
        .replace(/<\/(p|div|li|h[1-6])>/gi, "\n");
    const doc = new DOMParser().parseFromString(marked, "text/html");
    const text = (doc.body.textContent ?? "").replaceAll(" ", " ");

    // 마지막 문단 뒤에 붙은 줄바꿈 하나는 원문에 없던 것이다.
    return text.endsWith("\n") ? text.slice(0, -1) : text;
};
